-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- P99 is the content source; 5000 XP follows the vendored Dolvak version where P99 does not quantify XP. P99 example coin payout is fixed at 1p3g7s7c.
-- Migration 283 enables the existing spawn26618 at the exact P99 location (194,-781); its version=1 tag excluded it from the active zone. The unfinished Boysenberry Pie variant is not added.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Ah, hello, you must be the strangers that call yourselves friend to the Kin. Perhaps you would be interested in proving your worth?")
  elseif e.message:findi("proving") then
    e.self:Say("Good, then perhaps you would not mind performing a small task? Take this report to Eysa Florawhisper in the Wakening. She will give you a token indicating that she has received the message; return this to me for your reward.")
    e.other:SummonItem(29067)
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 29623 }) then
    e.self:Say("Your service is appreciated, " .. e.other:GetCleanName() .. ". I cannot reward you well at this point but you have come closer to the kin, the citizens of Skyshrine. Continue to prove your loyalty and greater rewards you may see, perhaps the greatest of all, in time.")
    e.other:Faction(430, 10, 0)
    e.other:Faction(436, 10, 0)
    e.other:Faction(448, -30, 0)
    e.other:AddEXP(5000)
    e.other:AddMoneyToPP(7, 7, 3, 1, true)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
